import * as C from './core.js';
import * as M from './model.js';
import { RealtimeSync } from './sync.js';
const $=s=>document.querySelector(s),E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>'฿ '+C.fmt(Math.round(n)),num=n=>Number(n||0).toLocaleString('th-TH'),when=v=>v?new Intl.DateTimeFormat('th-TH',{dateStyle:'medium',timeStyle:'short',timeZone:'Asia/Bangkok'}).format(new Date(v)):'ยังไม่มีการอัปเดต';
let s=M.fresh(),storageError='',resetDone=false;
try{if(!localStorage.getItem(M.RESET)){localStorage.removeItem(C.KEY);localStorage.setItem(M.RESET,'1');resetDone=true;}const raw=localStorage.getItem(M.KEY);if(raw)s=M.validate(JSON.parse(raw));}catch(err){storageError='อ่านข้อมูลไม่ได้: '+err.message+' กรุณาตรวจไฟล์สำรองก่อนบันทึกข้อมูลใหม่';}
let lastSavedRaw;try{lastSavedRaw=localStorage.getItem(M.KEY);}catch{lastSavedRaw=null;}
let cloud;
let page='overview',accountId='',gameId='',goalId='',gameTab='summary',filter='',modalPreviousFocus=null,undoState=null;
const pages={overview:'ภาพรวม',transactions:'รายการเงิน',accounts:'บัญชีของฉัน',games:'พัฒนาเกม',bills:'ค่าใช้จ่ายประจำ',debts:'หนี้สิน',goals:'เป้าหมาย',planning:'วางแผนชีวิต',settings:'ข้อมูลและการเชื่อมต่อ'};
const subtitles={overview:'สวัสดี Kanchit วันนี้เงินของคุณเป็นอย่างไรบ้าง',transactions:'บันทึกและตรวจสอบรายรับรายจ่าย',accounts:'ทุกบัญชี รวมเงินสด ดูรายการย้อนหลังได้ในที่เดียว',games:'บัญชีและผู้ช่วยวางแผนสำหรับนักพัฒนาเกม',bills:'ครบกำหนดเมื่อไร ค่อยกดบันทึกว่าจ่ายแล้ว',debts:'รู้ว่าติดหนี้ใคร เหลือเท่าไร และจะคืนเมื่อไร',goals:'วางแผนสิ่งที่อยากได้ ด้วยเงินที่เก็บไหว',planning:'วางแผนเงินใช้ เงินเก็บ และภาระผ่อน',settings:'สำรองข้อมูล ย้ายเครื่อง และจัดการการเชื่อมต่อ'};
const icons={overview:'◈',transactions:'↗',accounts:'▣',games:'✦',bills:'◷',debts:'⇄',goals:'◎',planning:'▤',settings:'⚙'};
const B=(text,action,cls='',id='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${id?`data-id="${E(id)}"`:''}>${text}</button>`;
const options=(list,value)=>list.map(([v,label])=>`<option value="${E(v)}" ${String(v)===String(value)?'selected':''}>${E(label)}</option>`).join('');
function field(name,label,value='',type='text',extra=''){return `<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" value="${E(value)}" type="${type}" ${extra}></div>`;}
const amt=(name,label,value='',required=true)=>field(name,label,value,'number',`step="0.01" min="0" ${required?'required':''}`);
const integer=(name,label,value=0,max=1000000000)=>field(name,label,value,'number',`min="0" max="${max}" step="1" required`);
const sel=(name,label,list,value='')=>`<div class="field"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}">${options(list,value)}</select></div>`;
const text=(name,label,value='',required=false)=>`<div class="field full"><label for="f-${name}">${label}</label><textarea id="f-${name}" name="${name}" maxlength="6000" ${required?'required':''}>${E(value)}</textarea></div>`;
const check=(name,label,value)=>`<label class="check-label"><input type="checkbox" name="${name}" ${value?'checked':''}>${label}</label>`;
const imageField=(image='')=>`<div class="field full"><label for="f-image">รูปปก</label><input id="f-image" type="file" name="image" accept="image/png,image/jpeg,image/webp"><small>PNG, JPG หรือ WebP สูงสุด 8 MB ระบบย่อรูปให้ก่อนเก็บในเครื่อง</small>${image?check('removeImage','ลบรูปปกเดิม',false):''}</div>`;
const empty=(title,description,action='',label='เพิ่มข้อมูล')=>`<div class="empty"><div class="empty-icon">＋</div><h3>${title}</h3><p>${description}</p>${action?B(label,action,'primary'):''}</div>`;
const panel=(title,body,action='')=>`<section class="panel"><div class="panel-head"><h2>${title}</h2>${action}</div>${body}</section>`;
const badge=(text,color='')=>`<span class="badge ${color}">${E(text)}</span>`;
const metric=(name,value)=>`<div class="metric-row"><span>${name}</span><strong>${value}</strong></div>`;
const notice=(message,color='')=>`<div class="notice ${color}">${message}</div>`;
function stats(items){return `<div class="grid stats-grid">${items.map(([label,value,hint=''],i)=>`<div class="stat ${i===0?'featured':''}"><div class="stat-top">${label}</div><div class="amount">${value}</div><small>${hint}</small></div>`).join('')}</div>`;}
function persist(){if(localStorage.getItem(M.KEY)!==lastSavedRaw)throw Error('ข้อมูลเปลี่ยนจากอีกแท็บ กรุณารีเฟรชก่อนบันทึก');s.updatedAt=M.updated();const raw=JSON.stringify(s);localStorage.setItem(M.KEY,raw);lastSavedRaw=raw;storageError='';cloud?.enqueue();}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3800);}
function mutate(fn,message='บันทึกแล้ว'){const before=structuredClone(s);try{fn();persist();undoState=before;render();toast(message);}catch(err){s=before;throw err;}}
function closeModal(){if($('#modal-root').innerHTML){$('#modal-root').innerHTML='';document.body.style.overflow='';modalPreviousFocus?.focus?.();}}
function modal(title,body,submit,label='บันทึก',wide=false){modalPreviousFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-header"><h2 id="modal-title">${title}</h2><button type="button" class="icon-button" data-action="close" aria-label="ปิดหน้าต่าง">×</button></header><form id="dialog-form"><div class="modal-body"><div class="formgrid">${body}</div><p class="form-error" role="alert" id="form-error"></p></div><footer class="modal-footer">${B('ยกเลิก','close')}<button class="btn primary" type="submit">${label}</button></footer></form></section></div>`;document.body.style.overflow='hidden';$('#dialog-form').onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;const before=structuredClone(s);try{await submit(Object.fromEntries(new FormData(e.target)),e.target);persist();undoState=before;closeModal();render();toast('บันทึกแล้ว');}catch(err){s=before;$('#form-error').textContent=err.message;button.disabled=false;}};$('#dialog-form input, #dialog-form textarea, #dialog-form select')?.focus();}
function confirmAction(title,description,fn){modal(title,`<div class="field full">${description}</div>`,()=>fn(),'ยืนยัน');}
function requireAccount(){if(!s.accounts.length){accountForm();toast('เพิ่มบัญชีหรือเงินสดก่อนบันทึกรายการ');return false;}return true;}
async function readImage(file){if(!file?.size)return null;if(file.size>8*1024*1024)throw Error('รูปต้องมีขนาดไม่เกิน 8 MB');if(!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('รองรับ PNG, JPG และ WebP');const bitmap=await createImageBitmap(file);const canvas=document.createElement('canvas'),ratio=Math.min(1,1000/bitmap.width,700/bitmap.height);canvas.width=Math.round(bitmap.width*ratio);canvas.height=Math.round(bitmap.height*ratio);canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close();return canvas.toDataURL('image/jpeg',.78);}
function accountForm(id=''){const a=s.accounts.find(a=>a.id===id);modal(a?'แก้ไขบัญชี':'เพิ่มบัญชี',field('name','ชื่อบัญชี',a?.name||'','text','required maxlength="80"')+sel('kind','ประเภทบัญชี',[['bank','บัญชีธนาคาร'],['cash','เงินสด'],['wallet','กระเป๋าเงินดิจิทัล']],a?.kind)+amt('opening','ยอดเริ่มต้น',a?C.inputMoney(a.opening):'')+field('bank','ธนาคาร / ผู้ให้บริการ',a?.bank||'','text','maxlength="100"')+text('note','รายละเอียด',a?.note||''),v=>{const row={id:id||C.uid(),name:v.name.trim(),kind:v.kind,opening:C.money(v.opening),bank:v.bank,note:v.note};if(!row.name)throw Error('ใส่ชื่อบัญชี');if(a)Object.assign(a,row);else s.accounts.push(row);});}
function deleteAccount(id){const a=s.accounts.find(a=>a.id===id),tx=s.transactions.filter(t=>t.accountId===id||t.toAccountId===id);confirmAction('ลบบัญชี '+E(a.name),`จะลบบัญชีและรายการเงิน ${tx.length} รายการที่เกี่ยวข้อง ต้นทุนและรายรับในหน้าเกมจะเก็บไว้โดยยกเลิกการเชื่อมบัญชี คุณกดย้อนกลับได้จนกว่าจะแก้ไขรายการถัดไป`,()=>{s.accounts=s.accounts.filter(a=>a.id!==id);s.transactions=s.transactions.filter(t=>t.accountId!==id&&t.toAccountId!==id);for(const g of s.games)for(const e of g.ledger)if(e.accountId===id)e.accountId='';accountId='';});}
function transactionForm(id='',pref={}){if(!requireAccount())return;const old=s.transactions.find(t=>t.id===id);if(old?.gameEntryId){const g=s.games.find(g=>g.id===old.gameId);gameEntryForm(g.id,old.gameEntryId);return;}const t=old||pref;modal(old?'แก้ไขรายการ':'บันทึกรายการ',sel('type','ประเภท',[['expense','รายจ่าย'],['income','รายรับ']],t.type||'expense')+amt('amount','จำนวนเงิน',t.amount?C.inputMoney(t.amount):'')+field('note','รายละเอียด',t.note||'','text','required maxlength="500"')+field('date','วันที่',t.date||C.today(),'date','required')+sel('accountId','บัญชี / เงินสด',s.accounts.map(a=>[a.id,a.name]),t.accountId||accountId)+sel('category','หมวด',C.categories.map(c=>[c,c]),t.category)+`${pref.uncertain?notice('ประเภทที่อ่านได้ยังไม่แน่ชัด กรุณาตรวจสอบ','yellow'):''}`+`${old?.debtId?notice('รายการชำระหนี้ กรุณาใช้หน้าหนี้สินเพื่อลงยอดคืนเพิ่ม'):''}`,v=>{if(old?.debtId)throw Error('แก้รายการคืนหนี้โดยลบรายการเดิมแล้วบันทึกคืนจากหน้าหนี้สิน');const amount=C.money(v.amount);if(amount<=0)throw Error('จำนวนเงินต้องมากกว่า 0');if(!M.validDate(v.date))throw Error('วันที่ไม่ถูกต้อง');if(pref.fingerprint&&s.transactions.some(r=>r.fingerprint===pref.fingerprint)&&!id)throw Error('ข้อความนี้บันทึกแล้ว กรุณาตรวจรายการเดิม');const row={id:id||C.uid(),...v,amount,...(pref.fingerprint?{fingerprint:pref.fingerprint}:{})};if(old)Object.assign(old,row);else s.transactions.push(row);});}
function smsForm(){modal('อ่านข้อความแจ้งรายการ',text('sms','วาง SMS หรือข้อความแจ้งเตือน','',true),v=>{const result=C.smsParse(v.sms);if(result.error)throw Error(result.error);const account=s.accounts.find(a=>result.bank&&(a.bank?.includes(result.bank)||a.name.includes(result.bank)));if(account)result.accountId=account.id;setTimeout(()=>transactionForm('',result),0);},'อ่านและเลือกหมวด');}
function deleteTransaction(id){const t=s.transactions.find(t=>t.id===id);confirmAction('ลบรายการเงิน',`ลบ ${E(t.note)} จำนวน ${money(t.amount)} ยอดบัญชีจะคำนวณใหม่${t.gameEntryId?' และลบรายการที่เชื่อมในหน้าเกมด้วย':''}`,()=>{if(t.gameEntryId){const g=s.games.find(g=>g.id===t.gameId);if(g)M.removeGameEntry(s,g,t.gameEntryId);}s.transactions=s.transactions.filter(r=>r.id!==id);});}
function transactionTable(rows){if(!rows.length)return empty('ยังไม่มีรายการ','รายการที่บันทึกจะแสดงที่นี่');return `<div class="table-wrap"><table><thead><tr><th>วันที่ / บัญชี</th><th>รายการ</th><th>หมวด</th><th class="tright">จำนวนเงิน</th><th>จัดการ</th></tr></thead><tbody>${[...rows].sort((a,b)=>b.date.localeCompare(a.date)).map(t=>`<tr><td>${C.dateText(t.date)}<br><small class="muted">${E(s.accounts.find(a=>a.id===t.accountId)?.name||'บัญชีถูกลบ')}</small></td><td>${E(t.note)}${t.gameEntryId?'<br>'+badge('จากหน้าเกม','blue'):''}</td><td>${E(t.category)}</td><td class="tright mono ${t.type==='income'?'positive':t.type==='transfer'?'':'negative'}">${t.type==='income'?'+':t.type==='transfer'?'↔':'−'}${money(t.amount)}</td><td><div class="table-actions">${t.type==='transfer'?'':B('แก้ไข','edit-tx','sm',t.id)}${B('ลบ','delete-tx','sm danger',t.id)}</div></td></tr>`).join('')}</tbody></table></div>`;}
function gameForm(id=''){const g=s.games.find(g=>g.id===id);modal(g?'แก้ไขโปรเจกต์เกม':'เพิ่มโปรเจกต์เกม',field('name','ชื่อเกม',g?.name||'','text','required maxlength="120"')+sel('status','สถานะ',[['idea','วางแผน'],['development','กำลังพัฒนา'],['testing','ทดสอบ / เดโม'],['published','เผยแพร่แล้ว'],['paused','พักโปรเจกต์']],g?.status||'development')+field('start','เริ่มพัฒนา',g?.start||C.today(),'date','required')+field('release','เป้าหมายเผยแพร่ / วันที่ขายจริง',g?.release||C.addMonths(C.today(),6),'date','required')+amt('budget','งบทั้งหมด',g?C.inputMoney(g.budget):'')+amt('price','ราคาขาย (บาท)',g?C.inputMoney(g.price):'')+field('fee','ส่วนแบ่งร้านค้า (%)',g?.fee??30,'number','step="0.01" min="0" max="100" required')+field('refund','สมมติฐานคืนเงิน (%)',g?.refund??0,'number','step="0.01" min="0" max="100" required')+field('weeklyHours','เวลาทำงานต่อสัปดาห์ (ชั่วโมง)',g?.weeklyHours??20,'number','min="1" max="168" step="0.5" required')+integer('bufferDays','วันเผื่อทดสอบก่อนขาย',g?.bufferDays??14,365)+field('appId','Steam App ID',g?.appId||'','text','pattern="[0-9]*" maxlength="12"')+field('genre','แนวเกม / กลุ่มผู้เล่น',g?.genre||'','text','maxlength="200"')+text('description','รายละเอียดและเป้าหมายของเกม',g?.description||'')+check('demoReady','เดโมพร้อมแล้ว',g?.demoReady)+check('storeReady','หน้าร้านพร้อมแล้ว',g?.storeReady)+imageField(g?.image),async v=>{const image=await readImage(v.image);if(v.release<v.start)throw Error('วันเผยแพร่ต้องไม่ก่อนวันเริ่มพัฒนา');const row={id:id||C.uid(),name:v.name.trim(),status:v.status,start:v.start,release:v.release,budget:C.money(v.budget),price:C.money(v.price),fee:Number(v.fee),refund:Number(v.refund),weeklyHours:Number(v.weeklyHours),bufferDays:Number(v.bufferDays),appId:v.appId.trim(),genre:v.genre,description:v.description,demoReady:v.demoReady==='on',storeReady:v.storeReady==='on',image:v.removeImage?'':image||g?.image||'',updatedAt:M.updated()};if(!row.name)throw Error('ใส่ชื่อเกม');if(g)Object.assign(g,row);else{s.games.push({...row,ledger:[],snapshots:[],reviews:[],milestones:[],lastDiscountEnd:'',lastPriceIncrease:''});gameId=row.id;gameTab='summary';}},'บันทึกโปรเจกต์',true);}
const statusLabel=g=>({idea:'วางแผน',development:'กำลังพัฒนา',testing:'ทดสอบ / เดโม',published:'เผยแพร่แล้ว',paused:'พักโปรเจกต์'})[g.status]||'กำลังพัฒนา';
function gameEntryForm(gid,id=''){const g=s.games.find(g=>g.id===gid),t=g.ledger.find(t=>t.id===id);modal(t?'แก้ไขรายการของเกม':'บันทึกเงินของเกม',sel('type','ประเภท',[['expense','ต้นทุน / รายจ่าย'],['income','รายรับ']],t?.type)+amt('amount','จำนวนเงิน (บาท)',t?C.inputMoney(t.amount):'')+field('note','รายละเอียด',t?.note||'','text','required maxlength="500"')+field('date','วันที่',t?.date||C.today(),'date','required')+sel('category','รายการต้นทุน',[['พัฒนาเกม','พัฒนาเกม'],['ซอฟต์แวร์','ซอฟต์แวร์'],['แอสเซต','แอสเซต'],['เสียงและดนตรี','เสียงและดนตรี'],['การตลาด','การตลาด'],['จ้างงาน','จ้างงาน'],['ค่าร้านค้า','ค่าร้านค้า'],['อุปกรณ์','อุปกรณ์'],['รายได้ขายเกม','รายได้ขายเกม'],['อื่น ๆ','อื่น ๆ']],t?.category)+sel('accountId','เชื่อมยอดบัญชีเงินจริง',[['','เฉพาะบัญชีเกม'],...s.accounts.map(a=>[a.id,a.name])],t?.accountId)+text('details','หมายเหตุ / ผู้ให้บริการ',t?.details||'')+`<div class="field full">${notice('เลือกบัญชีเมื่อเงินจ่ายออกหรือรับเข้าจริง ระบบสร้างรายการเงินให้เองครั้งเดียว หากเลือกเฉพาะบัญชีเกม ยอดเงินส่วนตัวจะไม่เปลี่ยน')}</div>`,v=>{const amount=C.money(v.amount);if(amount<=0)throw Error('จำนวนเงินต้องมากกว่า 0');M.putGameEntry(s,g,{...v,id:id||C.uid(),amount,updatedAt:M.updated()});});}
function snapshotForm(gid,id=''){const g=s.games.find(g=>g.id===gid),r=g.snapshots.find(r=>r.id===id),last=M.gameStats(g).last;modal('อัปเดต Wishlist และยอดขาย',field('date','วันที่ของข้อมูล',r?.date||C.today(),'date','required')+integer('views','ยอดเข้าชมสะสม',r?.views??last?.views??0)+integer('wishlists','Wishlist ปัจจุบัน',r?.wishlists??last?.wishlists??0)+integer('units','ยอดขายสะสม (ชุด)',r?.units??last?.units??0)+text('note','แหล่งข้อมูล / หมายเหตุ',r?.note||'')+`<div class="field full">${notice('ใช้ช่วงและนิยามข้อมูลให้เหมือนกันทุกครั้ง สถิติยอดขายไม่สร้างรายรับซ้ำ ให้บันทึกยอดรับเงินจริงในแท็บบัญชีเกม')}</div>`,v=>{const row={...v,id:id||C.uid(),views:Number(v.views),wishlists:Number(v.wishlists),units:Number(v.units),updatedAt:M.updated()};if(!M.validDate(row.date))throw Error('วันที่ไม่ถูกต้อง');const existing=g.snapshots.find(r=>r.date===v.date&&r.id!==id);if(existing)throw Error('วันที่นี้มีสถิติแล้ว กรุณาแก้รายการเดิม');if(r)Object.assign(r,row);else g.snapshots.push(row);g.updatedAt=M.updated();});}
function milestoneForm(gid,id=''){const g=s.games.find(g=>g.id===gid),m=g.milestones.find(m=>m.id===id);modal('แผนงานพัฒนา',field('name','งาน / หมุดหมาย',m?.name||'','text','required maxlength="200"')+field('due','กำหนดเสร็จ',m?.due||g.release,'date','required')+field('hours','ชั่วโมงที่เหลือโดยประมาณ',m?.hours??8,'number','step="0.5" min="0" max="100000" required')+check('done','ทำเสร็จแล้ว',m?.done),v=>{const row={...v,id:id||C.uid(),hours:Number(v.hours),done:v.done==='on'};if(m)Object.assign(m,row);else g.milestones.push(row);g.updatedAt=M.updated();});}
function reviewForm(gid,id=''){const g=s.games.find(g=>g.id===gid),r=g.reviews.find(r=>r.id===id);modal('บันทึกคอมเมนต์ / รีวิว',text('text','ข้อความรีวิว',r?.text||'',true)+sel('sentiment','ความเห็น',[['negative','เชิงลบ'],['positive','เชิงบวก'],['neutral','ทั่วไป / ยังไม่สรุป']],r?.sentiment)+field('author','ผู้เขียน',r?.author||'ผู้เล่น','text','maxlength="100"')+field('date','วันที่',r?.date||C.today(),'date','required'),v=>{const row={...v,id:id||C.uid(),topic:M.reviewTopic(v.text),source:'manual'};if(r)Object.assign(r,row);else g.reviews.push(row);g.updatedAt=M.updated();g.reviewsUpdatedAt=M.updated();});}
function reviewsImport(gid){modal('นำเข้ารีวิวจาก Steam / JSON',text('json','วาง JSON ที่มี reviews หรือรายการรีวิว')+`<div class="field full"><label for="f-file">หรือเลือกไฟล์ JSON</label><input type="file" name="file" id="f-file" accept=".json,application/json"></div><div class="field full">${notice('วิเคราะห์ประเด็นจากคำสำคัญ ไม่ส่งข้อความไปบริการ AI รีวิวที่มีรหัสเดิมจะถูกอัปเดตโดยไม่เพิ่มซ้ำ')}</div>`,async v=>{const raw=v.file?.size?await v.file.text():v.json;if(!raw.trim())throw Error('เลือกไฟล์หรือวาง JSON');if(raw.length>6000000)throw Error('ไฟล์ใหญ่เกิน 6 MB');const rows=M.importReviews(JSON.parse(raw)),g=s.games.find(g=>g.id===gid);for(const r of rows){const old=g.reviews.find(e=>e.id===r.id);if(old)Object.assign(old,r);else g.reviews.push(r);}g.updatedAt=M.updated();g.reviewsUpdatedAt=M.updated();});}
function billForm(id=''){const b=s.bills.find(b=>b.id===id);modal(b?'แก้ไขบิล':'เพิ่มค่าใช้จ่ายประจำ',field('name','ชื่อบิล',b?.name||'','text','required maxlength="150"')+amt('amount','จำนวนเงิน',b?C.inputMoney(b.amount):'')+field('due','กำหนดจ่ายรอบถัดไป',b?.due||C.today(),'date','required')+sel('frequency','ความถี่',[['monthly','รายเดือน'],['yearly','รายปี']],b?.frequency)+sel('active','สถานะ',[['true','ใช้งาน'],['false','ยกเลิก / พัก']],String(b?.active??true))+integer('remindDays','เตือนล่วงหน้า (วัน)',b?.remindDays??3,90)+text('note','รายละเอียด',b?.note||''),v=>{const row={...v,id:id||C.uid(),amount:C.money(v.amount),active:v.active==='true',day:Number(v.due.slice(8)),remindDays:Number(v.remindDays)};if(b)Object.assign(b,row);else s.bills.push(row);});}
function payBill(id){if(!requireAccount())return;const b=s.bills.find(b=>b.id===id);modal('จ่าย '+E(b.name),amt('amount','จำนวนที่จ่ายจริง',C.inputMoney(b.amount))+sel('accountId','จ่ายจากบัญชี',s.accounts.map(a=>[a.id,a.name]))+field('date','วันที่จ่าย',C.today(),'date','required')+`<div class="field full">${notice('บันทึกเป็นรายจ่ายและเลื่อนกำหนดบิลไปครั้งถัดไป')}</div>`,v=>{if(s.transactions.some(t=>t.billId===id&&t.billDue===b.due))throw Error('บิลรอบนี้บันทึกแล้ว');s.transactions.push({...v,id:C.uid(),amount:C.money(v.amount),type:'expense',category:'ที่พักและสาธารณูปโภค',note:b.name,billId:id,billDue:b.due});b.due=C.nextDue(b);});}
function debtForm(id=''){const d=s.debts.find(d=>d.id===id);modal(d?'แก้ไขหนี้':'เพิ่มหนี้ / ยืมเงิน',field('name','ติดหนี้ใคร / ชื่อเจ้าหนี้',d?.name||'','text','required maxlength="120"')+sel('kind','ประเภท',[['person','ยืมบุคคล'],['bank','สินเชื่อธนาคาร'],['card','บัตร / ผ่อนสินค้า']],d?.kind)+amt('principal',d?'เงินต้นตั้งต้น (ก่อนรายการคืนที่บันทึกไว้)':'เงินต้นที่ยังค้าง',d?C.inputMoney(d.principal):'')+amt('payment','ตั้งใจคืนต่อเดือน',d?C.inputMoney(d.payment):'')+field('apr','ดอกเบี้ยต่อปี (%)',d?.apr??0,'number','step="0.01" min="0" max="100" required')+field('due','กำหนดคืน / งวดถัดไป',d?.due||C.addMonths(C.today(),1),'date','required')+text('note','รายละเอียดการยืม / ข้อตกลง',d?.note||''),v=>{const row={...v,id:id||C.uid(),principal:C.money(v.principal),payment:C.money(v.payment),apr:Number(v.apr)};if(d)Object.assign(d,row);else s.debts.push(row);});}
function repay(id){if(!requireAccount())return;const d=s.debts.find(d=>d.id===id),left=C.outstanding(s,d);modal('คืนเงินให้ '+E(d.name),amt('amount','ยอดจ่ายทั้งหมด',C.inputMoney(Math.min(left,d.payment||left)))+amt('interest','ส่วนที่เป็นดอกเบี้ย / ค่าธรรมเนียม','0.00')+sel('accountId','จ่ายจากบัญชี',s.accounts.map(a=>[a.id,a.name]))+field('date','วันที่คืน',C.today(),'date','required')+field('nextDue','กำหนดคืนถัดไป',C.addMonths(d.due,1),'date','required'),v=>{const amount=C.money(v.amount),interest=C.money(v.interest),principal=amount-interest;if(amount<=0||principal<0||principal>left)throw Error('ตรวจยอดจ่าย ดอกเบี้ย และยอดเงินต้นค้าง');s.transactions.push({id:C.uid(),type:'expense',amount,principal,interest,debtId:id,accountId:v.accountId,date:v.date,category:'หนี้สิน',note:'คืนเงินให้ '+d.name});d.due=v.nextDue;});}
function goalForm(id=''){const g=s.goals.find(g=>g.id===id);modal(g?'แก้ไขเป้าหมาย':'เพิ่มเป้าหมาย',field('name','ชื่อเป้าหมาย',g?.name||'','text','required maxlength="120"')+amt('target','เงินเป้าหมาย',g?C.inputMoney(g.target):'')+amt('saved','เงินที่กันไว้แล้ว',g?C.inputMoney(g.saved):'0.00')+field('deadline','วันที่อยากทำสำเร็จ',g?.deadline||C.addMonths(C.today(),12),'date','required')+text('note','รายละเอียดเป้าหมาย',g?.note||'')+imageField(g?.image),async v=>{const target=C.money(v.target),saved=C.money(v.saved);if(target<=0)throw Error('เป้าหมายต้องมากกว่า 0');const image=await readImage(v.image),row={...v,id:id||C.uid(),target,saved,image:v.removeImage?'':image||g?.image||'',updatedAt:M.updated()};delete row.removeImage;if(g)Object.assign(g,row);else s.goals.push(row);});}
function holdingForm(id=''){const h=s.holdings.find(h=>h.id===id);modal('บันทึกการลงทุน',field('name','ชื่อสินทรัพย์ / กองทุน',h?.name||'','text','required maxlength="120"')+field('provider','ลงทุนที่ไหน',h?.provider||'','text','required maxlength="120"')+amt('cost','ต้นทุนรวม',h?C.inputMoney(h.cost):'')+amt('value','มูลค่าล่าสุด',h?C.inputMoney(h.value):'')+field('date','วันที่ประเมิน',h?.date||C.today(),'date','required')+text('note','รายละเอียด',h?.note||''),v=>{const row={...v,id:id||C.uid(),cost:C.money(v.cost),value:C.money(v.value)};if(h)Object.assign(h,row);else s.holdings.push(row);});}
function getAccountView(){const a=s.accounts.find(a=>a.id===accountId);if(!a){accountId='';return `<div class="cards">${s.accounts.map(a=>`<article class="account-card"><div class="row">${badge(a.kind==='cash'?'เงินสด':a.kind==='wallet'?'กระเป๋าดิจิทัล':a.bank||'ธนาคาร','blue')}<div class="actions">${B('แก้ไข','edit-account','sm',a.id)}${B('ลบ','delete-account','sm danger',a.id)}</div></div><button class="card-open" data-action="open-account" data-id="${a.id}"><h2>${E(a.name)}</h2><div class="amount">${money(C.balances(s)[a.id])}</div><span>ดูรายการใช้จ่าย →</span></button><small class="muted">ยอดเริ่มต้น ${money(a.opening)}</small></article>`).join('')}</div>${!s.accounts.length?empty('เพิ่มบัญชีแรกของคุณ','เลือกบัญชีธนาคาร เงินสด หรือกระเป๋าเงินดิจิทัล','add-account','เพิ่มบัญชี / เงินสด'):''}`;}const rows=s.transactions.filter(t=>t.accountId===a.id||t.toAccountId===a.id);return `${B('← ทุกบัญชี','back-accounts','ghost')}<div class="detail-title"><div><h2>${E(a.name)}</h2><p class="muted">${E(a.note||a.bank||'รายการในบัญชีนี้')}</p></div><div class="big-number">${money(C.balances(s)[a.id])}</div></div>${panel('ประวัติรายการ',transactionTable(rows),B('บันทึกรายการ','add-tx','primary'))}`;}
function overview(){const t=C.monthTotals(s),due=s.bills.filter(b=>b.active&&C.days(C.today(),b.due)<=b.remindDays).sort((a,b)=>a.due.localeCompare(b.due)),gameProfit=s.games.reduce((a,g)=>a+M.gameStats(g).profit,0);return `${!s.accounts.length?`<div class="welcome"><div class="text"><strong>ยินดีต้อนรับ Kanchit</strong><p>เพิ่มบัญชีหรือเงินสด แล้วตั้งยอดเริ่มต้นของคุณเอง</p></div>${B('＋ เพิ่มบัญชี','add-account','primary')}</div>`:''}${stats([['เงินรวมทุกบัญชี',money(C.totalCash(s)),'รวมเงินสดและกระเป๋าดิจิทัล'],['รายรับเดือนนี้',money(t.income),C.monthText(C.today())],['รายจ่ายเดือนนี้',money(t.expense),C.monthText(C.today())],['หนี้คงเหลือ',money(C.debtTotal(s)),s.debts.length+' เจ้าหนี้ / รายการ']])}<div class="dashboard-grid grid"><div>${panel('รายการล่าสุด',transactionTable(s.transactions.slice(-5)),B('ดูทั้งหมด','goto-transactions','ghost'))}${panel('โปรเจกต์เกม',s.games.length?s.games.map(g=>{const st=M.gameStats(g);return `<button class="project-row" data-action="open-game" data-id="${g.id}"><span class="project-mini">${g.image?`<img src="${g.image}" alt="">`:'✦'}</span><span class="grow"><strong>${E(g.name)}</strong><small>${statusLabel(g)} · อัปเดต ${when(g.updatedAt)}</small></span><span class="mono ${st.profit<0?'negative':'positive'}">${money(st.profit)} →</span></button>`}).join(''):empty('ยังไม่มีโปรเจกต์','เริ่มบันทึกงบ แผนงาน และสถิติของเกม','add-game','เพิ่มโปรเจกต์'))}</div><div>${panel('กำลังถึงกำหนด',due.length?due.map(b=>`<div class="reminder"><div class="reminder-body"><strong>${E(b.name)}</strong><small>${C.dateText(b.due)} ${C.days(C.today(),b.due)<0?'· เลยกำหนด':''}</small></div><b class="mono">${money(b.amount)}</b>${B('จ่ายแล้ว','pay-bill','sm',b.id)}</div>`).join(''):empty('ยังไม่มีบิลที่ต้องเตือน','แอปจะแสดงบิลเมื่อถึงช่วงเตือนล่วงหน้า'),B('ดูบิล','goto-bills','ghost'))}${panel('ภาพรวมแผนของคุณ',metric('เงินที่กันไว้ตามเป้าหมาย',money(C.totalReserved(s)))+metric('เงินหลังกันเป้าหมาย',money(C.totalCash(s)-C.totalReserved(s)))+metric('กำไร / ขาดทุนเกมทั้งหมด',money(gameProfit))+notice('ยอดเกมที่ไม่ได้เชื่อมบัญชีใช้วิเคราะห์โปรเจกต์ และไม่รวมในยอดเงินส่วนตัว'))}</div></div>`;}
function games(){if(gameId)return gameDetail();return `<div class="cards game-cards">${s.games.map(g=>{const st=M.gameStats(g);return `<article class="panel game-card"><button class="game-cover cover-button" data-action="open-game" data-id="${g.id}" ${g.image?`style="background-image:linear-gradient(0deg,#07162bca,#14274e22),url('${g.image}')"`:''}>${badge(statusLabel(g))}<h2>${E(g.name)}</h2><small>${E(g.genre||'โปรเจกต์เกม')}</small></button><div class="game-body">${metric('ต้นทุนจริง',money(st.costs))}${metric('รายรับจริง',money(st.revenue))}${metric('กำไร / ขาดทุน',`<span class="${st.profit<0?'negative':'positive'}">${money(st.profit)}</span>`)}<div class="row"><span>Wishlist <b>${num(st.last?.wishlists)}</b></span><small class="muted">${st.last?C.dateText(st.last.date):'ยังไม่เพิ่มสถิติ'}</small></div><small class="muted">อัปเดต ${when(g.updatedAt)}</small><div class="actions spacer">${B('เปิดรายละเอียด','open-game','primary',g.id)}${B('แก้ไข','edit-game','sm',g.id)}${B('ลบ','delete-game','sm danger',g.id)}</div></div></article>`}).join('')}</div>${!s.games.length?empty('พื้นที่ทำงานของนักพัฒนาเกม','เพิ่มโปรเจกต์ แล้วจัดการต้นทุน รายรับ แผนงาน Wishlist และรีวิวได้จากที่นี่','add-game','＋ เพิ่มโปรเจกต์เกม'):''}`;}
function gameDetail(){const g=s.games.find(g=>g.id===gameId);if(!g){gameId='';return games();}const st=M.gameStats(g),plan=M.releasePlan(g),tabs={summary:'ภาพรวมและผู้ช่วย',ledger:'บัญชีเกม',stats:'Wishlist / ยอดขาย',tasks:'แผนพัฒนา',reviews:'รีวิวและคอมเมนต์',discount:'วางแผนส่วนลด'};let body='';
 if(gameTab==='summary')body=`${stats([['กำไร / ขาดทุน',money(st.profit),'รายรับจริง − ต้นทุนจริง'],['ต้นทุนจริง',money(st.costs),'งบ '+money(g.budget)],['รายรับจริง',money(st.revenue),'ยอดที่บันทึกในบัญชีเกม'],['เงินที่ต้องคืนทุน',st.breakEven===null?'ยังคำนวณไม่ได้':num(st.breakEven)+' ชุด','จากราคาสุทธิตามสมมติฐาน']])}<div class="twocol">${panel('ผู้ช่วยโปรเจกต์',plan.tips.map(t=>`<div class="recommendation"><span>✦</span><p>${E(t)}</p></div>`).join('')+notice('คำแนะนำคำนวณจากข้อมูลที่คุณกรอก ไม่ใช่การคาดการณ์ยอดขายของตลาด'))}${panel('รายละเอียดโปรเจกต์',`<p class="prewrap">${E(g.description||'ยังไม่มีรายละเอียด')}</p>`+metric('เริ่มพัฒนา',C.dateText(g.start))+metric('เป้าหมายเผยแพร่',C.dateText(g.release))+metric('ระยะเวลาตามแผน',Math.max(0,Math.ceil(C.days(g.start,g.release)/30.4375))+' เดือน')+metric('พร้อมตามแผนงาน',C.dateText(plan.earliest))+metric('งบคงเหลือ',money(st.budgetLeft))+metric('Wishlist ล่าสุด',num(st.last?.wishlists))+metric('ขายสะสม',num(st.last?.units)+' ชุด')+metric('ข้อมูลอัปเดต',when(g.updatedAt)),B('แก้ไข','edit-game','sm',g.id))}</div>`;
 if(gameTab==='ledger'){const groups={};for(const t of g.ledger.filter(e=>e.type==='expense'))groups[t.category]=(groups[t.category]||0)+t.amount;body=`${stats([['ต้นทุนทั้งหมด',money(st.costs)],['รายรับทั้งหมด',money(st.revenue)],['กำไร / ขาดทุน',money(st.profit)],['งบคงเหลือ',money(st.budgetLeft)]])}${panel('รายการเงินของเกม',g.ledger.length?`<div class="table-wrap"><table><thead><tr><th>วันที่</th><th>รายละเอียด</th><th>ประเภทต้นทุน</th><th>เชื่อมบัญชี</th><th>จำนวนเงิน</th><th>จัดการ</th></tr></thead><tbody>${[...g.ledger].sort((a,b)=>b.date.localeCompare(a.date)).map(t=>`<tr><td>${C.dateText(t.date)}</td><td>${E(t.note)}<br><small class="muted">${E(t.details)}</small></td><td>${E(t.category)}</td><td>${E(s.accounts.find(a=>a.id===t.accountId)?.name||'เฉพาะบัญชีเกม')}</td><td class="mono ${t.type==='income'?'positive':'negative'}">${t.type==='income'?'+':'−'}${money(t.amount)}</td><td>${B('แก้ไข','edit-entry','sm',t.id)} ${B('ลบ','delete-entry','sm danger',t.id)}</td></tr>`).join('')}</tbody></table></div>`:empty('ยังไม่มีรายการของเกม','บันทึกได้โดยตรงที่นี่ เลือกเชื่อมกับบัญชีส่วนตัวได้เมื่อมีการรับหรือจ่ายเงินจริง','add-entry','เพิ่มรายรับ / ต้นทุน'),B('＋ เพิ่มรายรับ / ต้นทุน','add-entry','primary'))}${panel('ต้นทุนแยกตามประเภท',Object.keys(groups).length?Object.entries(groups).sort((a,b)=>b[1]-a[1]).map(([name,n])=>metric(E(name),money(n))).join(''):empty('ยังไม่มีต้นทุน','ประเภทต้นทุนจะแสดงตามรายการที่บันทึก'))}`;}
 if(gameTab==='stats')body=`${stats([['Wishlist ปัจจุบัน',num(st.last?.wishlists),st.last?C.dateText(st.last.date):'ยังไม่มีข้อมูล'],['เข้าชมสะสม',num(st.last?.views)],['ขายสะสม',num(st.last?.units)+' ชุด'],['เปลี่ยนจากครั้งก่อน',(st.last&&st.previous?(st.last.wishlists-st.previous.wishlists>=0?'+':'')+(st.last.wishlists-st.previous.wishlists):'—')]])}${panel('บันทึกสถิติ',g.snapshots.length?`<div class="table-wrap"><table><thead><tr><th>วันที่ข้อมูล</th><th>ผู้เข้าชมสะสม</th><th>Wishlist</th><th>ขายสะสม</th><th>อัปเดต</th><th>จัดการ</th></tr></thead><tbody>${st.snapshots.map(r=>`<tr><td>${C.dateText(r.date)}</td><td>${num(r.views)}</td><td>${num(r.wishlists)}</td><td>${num(r.units)}</td><td>${when(r.updatedAt)}</td><td>${B('แก้ไข','edit-snapshot','sm',r.id)} ${B('ลบ','delete-snapshot','sm danger',r.id)}</td></tr>`).join('')}</tbody></table></div>`:empty('เริ่มติดตาม Wishlist','กดอัปเดตสถิติ แล้วใส่วันที่ ผู้เข้าชม Wishlist และยอดขายจาก Steamworks','add-snapshot','＋ อัปเดตสถิติ'),B('＋ อัปเดตสถิติ','add-snapshot','primary'))}${notice('Wishlist เป็นยอดปัจจุบัน ส่วนผู้เข้าชมและยอดขายเป็นยอดสะสม โปรดใช้ตัวเลขช่วงเดียวกันทุกครั้ง รายรับยังต้องบันทึกในบัญชีเกม')}`;
 if(gameTab==='tasks')body=`<div class="twocol">${panel('แผนงานพัฒนา',g.milestones.length?g.milestones.map(m=>`<div class="milestone ${m.done?'done':''}"><input type="checkbox" data-task="${m.id}" aria-label="งาน ${E(m.name)}" ${m.done?'checked':''}><div class="info"><strong>${E(m.name)}</strong><br><small class="muted">${C.dateText(m.due)} · เหลือ ${m.hours} ชั่วโมง</small></div>${B('แก้ไข','edit-task','sm',m.id)}${B('ลบ','delete-task','sm danger',m.id)}</div>`).join(''):empty('เพิ่มงานที่เหลือ','ใส่ชั่วโมงและกำหนดเสร็จ ผู้ช่วยจะคำนวณวันพร้อมเผยแพร่','add-task','เพิ่มแผนงาน'),B('＋ เพิ่มงาน','add-task','primary'))}${panel('คำนวณเวลาพัฒนา',metric('เวลาทำงาน',g.weeklyHours+' ชั่วโมง / สัปดาห์')+metric('งานที่ยังไม่เสร็จ',plan.hours+' ชั่วโมง')+metric('วันเผื่อทดสอบ',g.bufferDays+' วัน')+metric('พร้อมไม่ก่อน',C.dateText(plan.earliest))+metric('เดือนเปิดขายตามแผน',plan.date?C.monthText(plan.date):'ยังไม่กำหนด')+notice('วันคำนวณรวมกำหนดงานที่ช้าที่สุด ควรเผื่อเวลาตรวจหน้าร้านและบิลด์ แล้วตรวจตารางกิจกรรมจริงก่อนประกาศขาย'),B('ปรับเวลาและวันเผยแพร่','edit-game','sm',g.id))}</div>`;
 if(gameTab==='reviews'){const summary=M.reviewSummary(g.reviews),positive=g.reviews.filter(r=>r.sentiment==='positive').length,negative=g.reviews.filter(r=>r.sentiment==='negative').length;body=`${stats([['รีวิวที่บันทึก',num(g.reviews.length)],['เชิงบวก',num(positive)],['เชิงลบ',num(negative)],['อัปเดตรีวิวล่าสุด',g.reviewsUpdatedAt?C.dateText(g.reviewsUpdatedAt.slice(0,10)):'—']])}<div class="actions spacer">${B('＋ เพิ่มรีวิว','add-review','primary')}${B('นำเข้า JSON','import-reviews')}${B('ดึงรีวิว Steam','fetch-reviews')}${g.appId?`<a class="btn" href="https://store.steampowered.com/app/${encodeURIComponent(g.appId)}/" target="_blank" rel="noopener">เปิดหน้าร้าน ↗</a>`:''}</div><div class="twocol section-gap">${panel('ประเด็นที่ควรแก้ก่อน',summary.length?summary.map((t,i)=>`<div class="recommendation"><span>${i+1}.</span><div><strong>${E(t.topic)}</strong><p>พบในรีวิวเชิงลบ ${t.count} รายการ ควรตรวจซ้ำและวางงานแก้ไข</p>${B('เพิ่มเป็นแผนงาน','review-task','sm',t.topic)}</div></div>`).join(''):empty('ยังไม่พบประเด็นซ้ำ','เพิ่มหรือนำเข้ารีวิวเพื่อจัดกลุ่มปัญหา')+notice('จัดกลุ่มด้วยคำสำคัญภาษาไทยและอังกฤษ อาจตีความผิดได้ ควรอ่านรีวิวประกอบ'))}${panel('รีวิวและคอมเมนต์',g.reviews.length?g.reviews.map(r=>`<article class="review"><div class="row"><strong>${E(r.author||'ผู้เล่น')}</strong>${badge(r.sentiment==='negative'?'เชิงลบ':r.sentiment==='positive'?'เชิงบวก':'ทั่วไป',r.sentiment==='negative'?'red':r.sentiment==='positive'?'green':'')}</div><p>${E(r.text)}</p><small class="muted">${E(r.topic)} · ${C.dateText(r.date)}</small><div class="actions spacer">${B('แก้ไข','edit-review','sm',r.id)}${B('ลบ','delete-review','sm danger',r.id)}</div></article>`).join(''):empty('ยังไม่มีรีวิว','เพิ่มด้วยตนเอง นำเข้า JSON หรือเชื่อม Steam ผ่านระบบหลังบ้าน'))}</div>`;}
 if(gameTab==='discount'){const d=M.discountPlan(g,g.discountPercent??20,g.discountUnits??100);body=`<div class="twocol">${panel('จำลองส่วนลด',`<form id="discount-form"><div class="formgrid">${field('percent','ลดราคา (%)',g.discountPercent??20,'number','min="0" max="95" step="1" required')+integer('units','ยอดขายฐานที่ต้องการเทียบ (ชุด)',g.discountUnits??100)+field('lastDiscountEnd','วันสิ้นสุดส่วนลดครั้งก่อน',g.lastDiscountEnd||'','date')+field('lastPriceIncrease','วันขึ้นราคาครั้งล่าสุด',g.lastPriceIncrease||'','date')}</div><button class="btn primary spacer">คำนวณและเก็บแผน</button><div id="discount-result" class="calc-result">${discountResult(d)}</div></form>`)}${panel('ควรลดเมื่อไร',notice(`ช่วงที่เสนอให้ตรวจสิทธิ์ลดราคาปกติ: ${C.dateText(d.earliest)}`,'yellow')+`<p class="small">เริ่มคำนวณหลังวันขาย 30 วัน และหลังจบส่วนลด/ขึ้นราคาครั้งล่าสุด 30 วัน เป็นการวางแผนเบื้องต้น มีข้อยกเว้นสำหรับบางกิจกรรมและส่วนลดเปิดตัว กรุณาตรวจสิทธิ์จริงใน Steamworks</p><div class="recommendation"><p>ถ้ายังพัฒนาอยู่ ให้เตรียมเดโมและหน้าร้านก่อน วางส่วนลดเปิดตัวแยกจากส่วนลดปกติ และเลือกกิจกรรมที่ตรงกับแนวเกม เมื่อเผยแพร่แล้ว ให้แก้ปัญหาที่ผู้เล่นพูดถึงก่อนเริ่มแคมเปญรอบใหม่</p></div><a class="btn" href="https://partner.steamgames.com/doc/marketing/discounts" target="_blank" rel="noopener">ตรวจเงื่อนไข Steam ↗</a>${notice('ราคาสุทธิประมาณจากส่วนแบ่งร้านค้าและอัตราคืนเงินที่กรอก ไม่รวมภาษี อัตราแลกเปลี่ยน หรือค่าธรรมเนียมอื่น')}`)}</div>`;}
 return `${B('← ทุกโปรเจกต์','back-games','ghost')}<div class="game-detail-header" ${g.image?`style="background-image:linear-gradient(90deg,#102449f2,#102449a8),url('${g.image}')"`:''}><div>${badge(statusLabel(g),'yellow')}<h1>${E(g.name)}</h1><p class="subtitle">${E(g.genre)} · อัปเดต ${when(g.updatedAt)}</p></div><div class="actions">${B('แก้ไขโปรเจกต์','edit-game','yellow',g.id)}${B('ลบ','delete-game','danger',g.id)}</div></div><nav class="tabs" aria-label="รายละเอียดเกม">${Object.entries(tabs).map(([key,label])=>`<button class="tab ${gameTab===key?'active':''}" data-game-tab="${key}">${label}</button>`).join('')}</nav>${body}`;
}
function discountResult(d){return metric('ราคาหลังลด',money(d.price))+metric('สุทธิต่อชุดประมาณ',money(d.unit))+metric('ขายเท่าเดิม จะรับสุทธิประมาณ',money(d.revenue))+metric('ต้องขายเพื่อให้ได้เท่าราคาปกติ',d.required===null?'คำนวณไม่ได้':num(d.required)+' ชุด')+`<small class="muted">สมมติจำนวนขาย ไม่ได้ทำนายว่าจะขายได้จริง</small>`;}
function goals(){const g=s.goals.find(g=>g.id===goalId);if(g){const p=C.goalPlan(g);return `${B('← ทุกเป้าหมาย','back-goals','ghost')}<div class="detail-title"><h2>${E(g.name)}</h2><div class="actions">${B('แก้ไข','edit-goal','primary',g.id)}${B('ลบ','delete-goal','danger',g.id)}</div></div><div class="twocol">${panel('รายละเอียดเป้าหมาย',`${g.image?`<img class="goal-detail-image" src="${g.image}" alt="รูปเป้าหมาย">`:''}<p class="prewrap">${E(g.note||'ยังไม่มีรายละเอียด')}</p>`+metric('เงินเป้าหมาย',money(g.target))+metric('เงินที่กันไว้แล้ว',money(g.saved))+metric('ยังขาด',money(p.left))+metric('อยากได้ภายใน',C.dateText(g.deadline))+metric('อัปเดตล่าสุด',when(g.updatedAt)))}${panel('แผนเก็บเงิน',`<div class="big-number">${money(p.monthly)} <small>/ เดือน</small></div>`+metric('เฉลี่ยต่อวัน',money(p.daily))+notice(p.overdue?'เลยวันที่ตั้งเป้าแล้ว ลองปรับกำหนดใหม่ หรือปรับยอดเก็บให้เหมาะกับรายได้':'ยอดเก็บคำนวณจากเงินที่ยังขาดและเวลาที่เหลือ','yellow')+B('ปรับเงินที่กันไว้ / เป้าหมาย','edit-goal','primary',g.id)+notice('เงินกันเป้าหมายยังอยู่ในบัญชี ไม่ถือเป็นรายจ่าย ตรวจว่าเงินสดจริงเพียงพอสำหรับทุกเป้าหมาย'))}</div>`;}return `<div class="cards">${s.goals.map(g=>{const p=C.goalPlan(g);return `<article class="panel goal-card">${g.image?`<button class="image-button" data-action="open-goal" data-id="${g.id}"><img src="${g.image}" alt="${E(g.name)}"></button>`:''}<button class="card-open" data-action="open-goal" data-id="${g.id}"><h2>${E(g.name)}</h2><div class="big-number">${money(g.saved)}</div><p class="muted">จาก ${money(g.target)}</p><div class="progress yellow"><i style="width:${Math.min(100,g.saved/g.target*100)}%"></i></div><p>เก็บ ${money(p.monthly)} / เดือน</p><small>ภายใน ${C.dateText(g.deadline)} →</small></button></article>`}).join('')}</div>${!s.goals.length?empty('กำลังเก็บเงินเพื่ออะไรอยู่','เพิ่มเป้าหมายพร้อมรูป แล้วดูยอดเก็บต่อเดือนและต่อวัน','add-goal','เพิ่มเป้าหมาย'):''}`;}
function bills(){return notice('แจ้งเตือนเมื่อเปิดแอป ไม่มีการหักบัญชีอัตโนมัติ ดาวน์โหลดปฏิทินเพื่อนำเข้าแอปปฏิทินและตั้งเตือนขณะปิดเว็บได้')+`<div class="actions spacer">${B('ดาวน์โหลดบิลเป็นปฏิทิน','calendar')}</div><div class="cards section-gap">${s.bills.map(b=>`<article class="panel"><div class="row"><h2>${E(b.name)}</h2>${badge(b.active?'ใช้งาน':'พัก / ยกเลิก',b.active?'blue':'')}</div><div class="big-number">${money(b.amount)}</div><p>${C.dateText(b.due)} · ${b.frequency==='monthly'?'รายเดือน':'รายปี'}</p><p class="muted small">${E(b.note)}</p>${b.active?notice(C.days(C.today(),b.due)<0?'เลยกำหนดจ่ายแล้ว':`อีก ${C.days(C.today(),b.due)} วัน · เตือนล่วงหน้า ${b.remindDays} วัน`,C.days(C.today(),b.due)<=b.remindDays?'yellow':''):''}<div class="actions">${b.active?B('จ่ายแล้ว','pay-bill','primary',b.id):''}${B('แก้ไข / ยกเลิก','edit-bill','sm',b.id)}${B('ลบ','delete-bill','sm danger',b.id)}</div></article>`).join('')}</div>${!s.bills.length?empty('ยังไม่มีค่าใช้จ่ายประจำ','เพิ่มกำหนดจ่ายค่าเน็ต ค่าสมาชิก หรือบิลอื่น ๆ','add-bill'):''}`;}
function debts(){return `${stats([['หนี้คงเหลือ',money(C.debtTotal(s))],['ภาระต่อเดือน',money(C.monthlyDebt(s))],['เจ้าหนี้ / รายการ',num(s.debts.length)],['คืนเงินต้นแล้ว',money(s.transactions.filter(t=>t.debtId).reduce((a,t)=>a+(t.principal||0),0))]])}<div class="cards">${s.debts.map(d=>{const left=C.outstanding(s,d),p=left?C.payoff(left,d.apr,d.payment):{months:0,interest:0};return `<article class="panel"><div class="row"><h2>${E(d.name)}</h2>${badge(d.kind==='person'?'ยืมบุคคล':'สินเชื่อ / ผ่อน')}</div><div class="big-number">${money(left)}</div>${metric('ตั้งใจคืนต่อเดือน',money(d.payment))}${metric('ดอกเบี้ยต่อปี',d.apr+'%')}${metric('กำหนดคืน',C.dateText(d.due))}<p class="muted small prewrap">${E(d.note)}</p>${notice(p?(left?'ประมาณ '+p.months+' เดือน ดอกเบี้ย '+money(p.interest):'คืนเงินต้นครบแล้ว'):'ค่างวดไม่พอตัดเงินต้น กรุณาปรับยอดคืน','yellow')}<small class="muted">ประมาณแบบลดต้นลดดอก อัตราคงที่ ไม่รวมค่าธรรมเนียม</small><div class="actions spacer">${left?B('บันทึกคืนเงิน','repay','primary',d.id):''}${B('แก้ไข','edit-debt','sm',d.id)}${B('ลบ','delete-debt','sm danger',d.id)}</div></article>`}).join('')}</div>${!s.debts.length?empty('บันทึกว่าติดหนี้ใครบ้าง','เพิ่มชื่อคนที่ยืมเงิน เจ้าหนี้ธนาคาร หรือยอดผ่อนสินค้า','add-debt'):''}${panel('ประวัติคืนเงิน',transactionTable(s.transactions.filter(t=>t.debtId)))}`;}
function planning(){const free=s.profile.income-s.profile.living-C.monthlyBill(s)-C.monthlyDebt(s),reserve=s.profile.living*s.profile.reserveMonths;return `<div class="twocol">${panel('แผนรายเดือนของ Kanchit',`<form id="profile-form"><div class="formgrid">${amt('income','รายได้ที่คาดต่อเดือน',C.inputMoney(s.profile.income))+amt('living','ค่าใช้ชีวิตต่อเดือน (ไม่รวมบิลและหนี้)',C.inputMoney(s.profile.living))+field('reserveMonths','อยากสำรองค่าใช้ชีวิตกี่เดือน',s.profile.reserveMonths,'number','min="1" max="24" required')+sel('risk','ความเสี่ยงที่รับได้',[['low','ต่ำ'],['medium','ปานกลาง'],['high','สูง']],s.profile.risk)}</div><button class="btn primary spacer">บันทึกแผน</button></form><div class="calc-result">${metric('บิลประจำเฉลี่ยต่อเดือน',money(C.monthlyBill(s)))}${metric('ภาระหนี้ต่อเดือน',money(C.monthlyDebt(s)))}${metric('คงเหลือหลังภาระที่กรอก',money(free))}${metric('เงินสำรองค่าใช้ชีวิตเป้าหมาย',money(reserve))}</div>${notice('เงินสำรองนี้คิดเฉพาะค่าใช้ชีวิตที่กรอก ยังไม่รวมบิลและหนี้ ควรเพิ่มเงินสำรองให้ครอบคลุมภาระจริง')}`)}${panel('จำลองสินเชื่อ',`<form id="loan-form"><div class="formgrid">${amt('amount','วงเงินที่ต้องการ',C.inputMoney(s.loan.amount))+field('apr','ดอกเบี้ยต่อปี (%)',s.loan.apr,'number','min="0" max="100" step="0.01" required')+field('months','ระยะเวลาผ่อน (เดือน)',s.loan.months,'number','min="1" max="600" required')+field('ratio','เพดานภาระผ่อนที่คุณตั้ง (% รายได้)',s.loan.ratio,'number','min="1" max="100" required')}</div><button class="btn primary spacer">คำนวณและบันทึก</button></form><div class="calc-result" id="loan-result">${loanResult()}</div><a class="btn spacer" href="https://app.bot.or.th/1213/MCPD/ProductApp" target="_blank" rel="noopener">เปรียบเทียบสินเชื่อ ธปท. ↗</a>${notice('ใช้ประเมินกระแสเงินสดเบื้องต้น ไม่ใช่เกณฑ์อนุมัติ ธนาคารยังพิจารณารายได้ เอกสาร เครดิต และเงื่อนไขของแต่ละผลิตภัณฑ์')}`)}</div><div class="section-gap">${panel('การลงทุนของฉัน',s.holdings.length?`<div class="table-wrap"><table><thead><tr><th>สินทรัพย์ / ที่ลงทุน</th><th>ต้นทุน</th><th>มูลค่าล่าสุด</th><th>กำไร / ขาดทุน</th><th>วันที่</th><th>จัดการ</th></tr></thead><tbody>${s.holdings.map(h=>`<tr><td>${E(h.name)}<br><small>${E(h.provider)}</small></td><td>${money(h.cost)}</td><td>${money(h.value)}</td><td class="${h.value<h.cost?'negative':'positive'}">${money(h.value-h.cost)}</td><td>${C.dateText(h.date)}</td><td>${B('แก้ไข','edit-holding','sm',h.id)} ${B('ลบ','delete-holding','sm danger',h.id)}</td></tr>`).join('')}</tbody></table></div>`:empty('ยังไม่บันทึกการลงทุน','ติดตามต้นทุน มูลค่า และสถานที่ลงทุน ยอดนี้ไม่หักบัญชีอัตโนมัติ'),B('＋ บันทึกการลงทุน','add-holding','primary'))}${notice(C.totalCash(s)<reserve||free<=0?'จากแผนที่กรอก ควรตรวจเงินสำหรับค่าใช้ชีวิต บิล และหนี้ให้เพียงพอก่อนจัดงบลงทุนเพิ่ม':'แผนมีส่วนเหลือเบื้องต้น ลองแบ่งเงินสำรองและเป้าหมายก่อนกำหนดงบลงทุน พร้อมศึกษาความเสี่ยงและค่าธรรมเนียม')}${B('ศึกษากองทุนและการเชื่อมต่อ','goto-settings','ghost')}</div>`;}
function loanResult(){const p=C.pmt(s.loan.amount,s.loan.apr,s.loan.months),ratio=s.profile.income?(C.monthlyDebt(s)+p)/s.profile.income*100:null;return metric('ค่างวดใหม่ประมาณ',money(p)+' / เดือน')+metric('ดอกเบี้ยรวมประมาณ',money(p*s.loan.months-s.loan.amount))+metric('ภาระหนี้รวมต่อรายได้',ratio===null?'กรอกรายได้ก่อน':ratio.toFixed(1)+'%')+notice(ratio===null?'ยังประเมินไม่ได้จนกว่าจะกรอกรายได้':ratio>s.loan.ratio?'เกินเพดานภาระที่คุณตั้ง ลองลดวงเงินหรือปรับแผน':'อยู่ในเพดานที่คุณตั้ง ตรวจยอดเหลือใช้และเงื่อนไขธนาคารต่อ','yellow');}
function settings(){return `<div class="twocol">${panel('ข้อมูลส่วนตัวและการสำรอง',`<p>เว็บหลักซิงก์ข้อมูลและรูปผ่านฐานข้อมูลส่วนตัว ใช้บัญชี ChatGPT เดียวกันบนมือถือและคอม ข้อมูลส่วนตัวไม่ถูกใส่ในซอร์ส GitHub</p>${notice('ขณะออนไลน์ การบันทึกจะส่งขึ้นคลาวด์และอัปเดตเครื่องอื่นอัตโนมัติ หากออฟไลน์ข้อมูลจะรอส่งในเครื่อง ดูสถานะซิงก์ด้านบนก่อนปิดหน้า การนำเข้า JSON จะแทนที่ข้อมูลและซิงก์การเปลี่ยนแปลงไปทุกเครื่อง')}<div class="actions">${B('ดาวน์โหลดสำรอง JSON','export','primary')}${B('นำเข้าข้อมูลสำรอง','import')}${B('ส่งออกรายการ CSV','csv')}</div><div class="actions spacer">${B('ล้างข้อมูลทั้งหมด','reset','danger')}</div><p class="source-note">อัปเดตข้อมูลล่าสุด ${when(s.updatedAt)}</p>`)}${panel('การเชื่อมต่อ Steam',`<p>Wishlist และยอดขายเป็นข้อมูลผู้เผยแพร่ ต้องใช้ Publisher Key ที่มีสิทธิ์ Financial เก็บในระบบหลังบ้าน รีวิวสาธารณะอ่านได้ผ่าน API</p>${notice('GitHub Pages ให้บริการไฟล์หน้าเว็บ จึงเก็บกุญแจ Steam หรือรหัสธนาคารไว้ในโค้ดไม่ได้ รุ่นนี้เพิ่มสถิติเองและนำเข้ารีวิว JSON ได้ทันที')}<form id="bridge-form"><div class="field"><label for="bridge-url">URL ระบบหลังบ้านสำหรับรีวิว (ถ้ามี)</label><input type="url" id="bridge-url" name="bridgeUrl" value="${E(s.settings?.bridgeUrl||'')}" placeholder="https://your-worker.workers.dev"></div><div class="field spacer"><label for="bridge-token">โทเคนของระบบหลังบ้าน</label><input id="bridge-token" name="token" type="password" autocomplete="off"><small>เก็บในเซสชันของแท็บนี้ ไม่นำไปรวมไฟล์สำรอง</small></div><button class="btn primary spacer">บันทึกการเชื่อมต่อ</button></form><div class="link-list"><a href="https://partner.steamgames.com/doc/webapi/IPartnerFinancialsService" target="_blank" rel="noopener">เอกสาร Wishlist / Sales API ↗</a><a href="https://partner.steamgames.com/doc/webapi/IUserReviewsService" target="_blank" rel="noopener">เอกสารรีวิว API ↗</a></div>`)}</div><div class="cards section-gap">${panel('ธนาคารและเงินสด',`${badge('ยังไม่เชื่อมอัตโนมัติ','yellow')}<p class="small spacer">ใช้การวางข้อความแจ้งรายการในหน้ารายการเงินได้ ธนาคารต้องรองรับการให้สิทธิ์ผ่านผู้ให้บริการอย่างเป็นทางการ แอปนี้ยังไม่ได้เป็นผู้ให้บริการ Open Banking</p><div class="link-list"><a href="https://www.bot.or.th/th/financial-innovation/digital-finance/open-data/Your_Data_Project.html" target="_blank" rel="noopener">โครงการ Your Data ของ ธปท. ↗</a></div>`)}${panel('กองทุนและการลงทุน',`<p class="small">SEC Fund Check ใช้ตรวจนโยบาย ความเสี่ยง ค่าธรรมเนียม และเอกสารกองทุน แอปนี้ยังไม่ได้ดึง NAV หรือจัดอันดับกองทุนแบบเรียลไทม์</p><div class="link-list"><a href="https://fundcheck.sec.or.th" target="_blank" rel="noopener">เปิด SEC Fund Check ↗</a></div>`)}${panel('ปฏิทินและการใช้งานหลายเครื่อง',`<p class="small">ยอดซิงก์แบบเรียลไทม์เมื่อเปิดเว็บหลักและออนไลน์ การแจ้งเตือนบิลขณะปิดเว็บยังใช้ส่งออก .ics เพื่อนำเข้าปฏิทินมือถือ</p><div class="actions spacer">${B('ดาวน์โหลดปฏิทินบิล','calendar')}</div>`)}</div>`;}
function render(){let content='';if(page==='overview')content=overview();if(page==='accounts')content=getAccountView();if(page==='games')content=games();if(page==='goals')content=goals();if(page==='bills')content=bills();if(page==='debts')content=debts();if(page==='planning')content=planning();if(page==='settings')content=settings();if(page==='transactions'){const rows=s.transactions.filter(t=>(!filter||[t.note,t.category].some(v=>String(v).toLowerCase().includes(filter.toLowerCase()))));content=`<div class="filterbar"><input id="search" aria-label="ค้นหารายการเงิน" placeholder="ค้นหารายละเอียดหรือหมวด" value="${E(filter)}">${B('อ่านข้อความแจ้งรายการ','sms')}${B('ส่งออก CSV','csv')}</div>${panel('รายรับรายจ่ายทั้งหมด',transactionTable(rows))}`;}
const addActions={overview:['บันทึกรายการ','add-tx'],transactions:['บันทึกรายการ','add-tx'],accounts:['บัญชี / เงินสด','add-account'],games:['โปรเจกต์เกม','add-game'],goals:['เป้าหมาย','add-goal'],bills:['บิลประจำ','add-bill'],debts:['หนี้ / ยืมเงิน','add-debt'],planning:['บันทึกการลงทุน','add-holding']};const add=addActions[page];
$('#app').innerHTML=`<header class="app-header"><div class="header-inner"><a class="brand" href="#overview" data-page="overview"><div class="brandmark">฿</div><div><strong>สมุดเงินของครรชิต</strong><span>KANCHIT'S BANKBOOK</span></div></a><div class="header-meta"><span>${C.dateText(C.today())}</span><span class="user-chip">Kanchit</span></div></div><nav class="horizontal-nav" aria-label="เมนูหลัก">${Object.entries(pages).map(([key,label])=>`<button class="nav-item ${page===key?'active':''}" data-page="${key}" aria-current="${page===key?'page':'false'}"><span>${icons[key]}</span>${label}</button>`).join('')}</nav></header><main class="content"><header class="page-heading"><div><div class="eyebrow">KANCHIT'S PERSONAL NOTEBOOK</div><h1>${pages[page]}</h1><p class="subtitle">${subtitles[page]}</p></div><div class="actions">${undoState?B('↶ ย้อนกลับ','undo'):''}${add?B('＋ '+add[0],add[1],'primary'):''}</div></header><div id="sync-slot"></div>${storageError?notice(E(storageError),'red'):''}${resetDone?notice('ล้างข้อมูลทดสอบรุ่นเดิมแล้ว เริ่มกรอกข้อมูลจริงได้เลย','green'):''}${content}<footer class="footer"><span>สมุดเงินของครรชิต · Kanchit</span><span>บัญชีส่วนตัว · Asia/Bangkok · THB</span></footer></main>`;
bindForms();renderSync();}
function bindForms(){const pf=$('#profile-form');if(pf)pf.onsubmit=e=>{e.preventDefault();try{const v=Object.fromEntries(new FormData(pf));mutate(()=>s.profile={...s.profile,income:C.money(v.income),living:C.money(v.living),reserveMonths:Number(v.reserveMonths),risk:v.risk});}catch(err){toast(err.message)}};const lf=$('#loan-form');if(lf)lf.onsubmit=e=>{e.preventDefault();try{const v=Object.fromEntries(new FormData(lf));mutate(()=>s.loan={amount:C.money(v.amount),apr:Number(v.apr),months:Number(v.months),ratio:Number(v.ratio)});}catch(err){toast(err.message)}};const df=$('#discount-form');if(df)df.onsubmit=e=>{e.preventDefault();try{const v=Object.fromEntries(new FormData(df)),g=s.games.find(g=>g.id===gameId);mutate(()=>{g.lastDiscountEnd=v.lastDiscountEnd;g.lastPriceIncrease=v.lastPriceIncrease;g.discountPercent=Number(v.percent);g.discountUnits=Number(v.units);g.updatedAt=M.updated();},'เก็บสมมติฐานส่วนลดแล้ว');$('#f-percent').value=v.percent;$('#f-units').value=v.units;$('#discount-result').innerHTML=discountResult(M.discountPlan(g,Number(v.percent),Number(v.units)));}catch(err){toast(err.message)}};const bf=$('#bridge-form');if(bf)bf.onsubmit=e=>{e.preventDefault();try{const v=Object.fromEntries(new FormData(bf));let url=v.bridgeUrl.trim().replace(/\/$/,'');if(url){const u=new URL(url);if(u.protocol!=='https:')throw Error('ใช้ URL แบบ HTTPS');}sessionStorage.setItem('kanchit-bridge-token',v.token);mutate(()=>s.settings={...s.settings,bridgeUrl:url},'บันทึกแล้ว ไปหน้าเกมเพื่อดึงรีวิว');}catch(err){toast(err.message)}};}
function download(content,name,type){const u=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),2000);}
function exportCsv(){const escape=v=>'"'+String(v??'').replace(/^[=+\-@]/,"'$&").replace(/"/g,'""')+'"';const rows=[['วันที่','ประเภท','รายละเอียด','หมวด','บัญชี','จำนวนเงิน'],...s.transactions.map(t=>[t.date,t.type,t.note,t.category,s.accounts.find(a=>a.id===t.accountId)?.name||'',C.inputMoney(t.amount)])];download('\ufeff'+rows.map(r=>r.map(escape).join(',')).join('\r\n'),'kanchit-transactions-'+C.today()+'.csv','text/csv;charset=utf-8');}
function exportCalendar(){const esc=v=>String(v).replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;');const events=s.bills.filter(b=>b.active).map(b=>['BEGIN:VEVENT','UID:'+b.id+'@kanchit-bankbook','DTSTAMP:'+new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,''),'DTSTART;VALUE=DATE:'+b.due.replace(/-/g,''),'SUMMARY:'+esc('จ่าย '+b.name+' '+money(b.amount)),`RRULE:FREQ=${b.frequency==='yearly'?'YEARLY':'MONTHLY'};COUNT=12`,'DESCRIPTION:'+esc('บันทึกว่าจ่ายแล้วในสมุดเงินด้วยตนเอง'),'BEGIN:VALARM','TRIGGER:-P'+(b.remindDays||1)+'D','ACTION:DISPLAY','DESCRIPTION:'+esc('ใกล้กำหนดจ่าย '+b.name),'END:VALARM','END:VEVENT'].join('\r\n'));download(['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Kanchit//Bankbook//TH',...events,'END:VCALENDAR'].join('\r\n'),'kanchit-bills.ics','text/calendar');}
function backupImport(){modal('นำเข้าข้อมูลสำรอง',`<div class="field full"><label for="backup-file">ไฟล์สำรอง JSON รุ่น 2</label><input type="file" name="backup" id="backup-file" accept=".json" required>${notice('จะแทนที่ข้อมูลปัจจุบันทั้งหมด กดย้อนกลับได้หลังนำเข้าสำเร็จ')}</div>`,async v=>{if(v.backup.size>10000000)throw Error('ไฟล์ใหญ่เกิน 10 MB');s=M.validate(JSON.parse(await v.backup.text()));});}
async function fetchReviews(){const g=s.games.find(g=>g.id===gameId);if(!g.appId){toast('เพิ่ม Steam App ID ในรายละเอียดโปรเจกต์ก่อน');return gameForm(g.id);}const base=s.settings?.bridgeUrl;if(!base){toast('ตั้งค่า URL ระบบหลังบ้านในหน้าการเชื่อมต่อ หรือนำเข้า JSON ได้ทันที');return reviewsImport(g.id);}try{toast('กำลังดึงรีวิวผ่านระบบหลังบ้านของคุณ…');const token=sessionStorage.getItem('kanchit-bridge-token')||'',r=await fetch(base+'/reviews?appid='+encodeURIComponent(g.appId),{headers:token?{Authorization:'Bearer '+token}:{},signal:AbortSignal.timeout(20000)});if(!r.ok)throw Error('ระบบหลังบ้านตอบกลับ '+r.status);const rows=M.importReviews(await r.json());mutate(()=>{for(const row of rows){const old=g.reviews.find(r=>r.id===row.id);if(old)Object.assign(old,row);else g.reviews.push(row);}g.updatedAt=M.updated();g.reviewsUpdatedAt=M.updated();},'อัปเดตรีวิว '+rows.length+' รายการแล้ว');}catch(err){toast('ดึงรีวิวไม่ได้: '+err.message+' ใช้นำเข้า JSON ได้');}}
function deleteGame(id){const g=s.games.find(g=>g.id===id);confirmAction('ลบโปรเจกต์ '+E(g.name),`จะลบรายละเอียดเกม สถิติ แผนงาน รีวิว และบัญชีเกมทั้งหมด รายการรับจ่ายที่เชื่อมบัญชีเงินจริงจะเก็บไว้เป็นประวัติส่วนตัว`,()=>{s.games=s.games.filter(g=>g.id!==id);for(const t of s.transactions.filter(t=>t.gameId===id)){delete t.gameId;delete t.gameEntryId;}gameId='';});}
document.addEventListener('click',async e=>{const target=e.target.closest('[data-page],[data-action],[data-game-tab]');if(!target)return;try{if(target.dataset.page){e.preventDefault();page=target.dataset.page;accountId=gameId=goalId='';resetDone=false;render();return;}if(target.dataset.gameTab){gameTab=target.dataset.gameTab;render();return;}const a=target.dataset.action,id=target.dataset.id,g=s.games.find(g=>g.id===gameId);if(a==='close')return closeModal();if(a.startsWith('goto-')){page=a.slice(5);accountId=gameId=goalId='';render();return;}
const handlers={
 'add-account':()=>accountForm(),'edit-account':()=>accountForm(id),'delete-account':()=>deleteAccount(id),'open-account':()=>{page='accounts';accountId=id;render();},'back-accounts':()=>{accountId='';render();},
 'add-tx':()=>transactionForm(),'edit-tx':()=>transactionForm(id),'delete-tx':()=>deleteTransaction(id),sms:smsForm,
 'add-game':()=>gameForm(),'edit-game':()=>gameForm(id),'delete-game':()=>deleteGame(id),'open-game':()=>{page='games';gameId=id;gameTab='summary';render();},'back-games':()=>{gameId='';render();},
 'add-entry':()=>gameEntryForm(g.id),'edit-entry':()=>gameEntryForm(g.id,id),'delete-entry':()=>confirmAction('ลบรายการเกม','รายการที่เชื่อมบัญชีจะถูกลบจากบัญชีส่วนตัวด้วย',()=>M.removeGameEntry(s,g,id)),
 'add-snapshot':()=>snapshotForm(g.id),'edit-snapshot':()=>snapshotForm(g.id,id),'delete-snapshot':()=>confirmAction('ลบสถิติ','ลบสถิติวันที่เลือก',()=>{g.snapshots=g.snapshots.filter(r=>r.id!==id);g.updatedAt=M.updated();}),
 'add-task':()=>milestoneForm(g.id),'edit-task':()=>milestoneForm(g.id,id),'delete-task':()=>confirmAction('ลบแผนงาน','ลบงานที่เลือกและคำนวณวันพร้อมใหม่',()=>{g.milestones=g.milestones.filter(m=>m.id!==id);g.updatedAt=M.updated();}),
 'add-review':()=>reviewForm(g.id),'edit-review':()=>reviewForm(g.id,id),'import-reviews':()=>reviewsImport(g.id),'fetch-reviews':fetchReviews,'delete-review':()=>confirmAction('ลบรีวิว','ลบรีวิวนี้ออกจากสมุดเงิน ไม่ได้ลบจาก Steam',()=>{g.reviews=g.reviews.filter(r=>r.id!==id);g.updatedAt=M.updated();}),
 'review-task':()=>{milestoneForm(g.id);$('#f-name').value='ตรวจและแก้: '+id;},
 'add-bill':()=>billForm(),'edit-bill':()=>billForm(id),'pay-bill':()=>payBill(id),'delete-bill':()=>confirmAction('ลบบิล','ลบกำหนดบิล ประวัติรายจ่ายที่เคยจ่ายแล้วยังเก็บไว้',()=>s.bills=s.bills.filter(b=>b.id!==id)),
 'add-debt':()=>debtForm(),'edit-debt':()=>debtForm(id),repay:()=>repay(id),'delete-debt':()=>confirmAction('ลบข้อมูลหนี้','ลบยอดหนี้และข้อมูลเจ้าหนี้ ประวัติรายจ่ายที่คืนแล้วยังเก็บไว้',()=>{s.debts=s.debts.filter(d=>d.id!==id);for(const t of s.transactions.filter(t=>t.debtId===id))delete t.debtId;}),
 'add-goal':()=>goalForm(),'edit-goal':()=>goalForm(id),'open-goal':()=>{goalId=id;render();},'back-goals':()=>{goalId='';render();},'delete-goal':()=>confirmAction('ลบเป้าหมาย','เงินในบัญชีจะไม่เปลี่ยน การกันเงินเป้าหมายนี้จะถูกยกเลิก',()=>{s.goals=s.goals.filter(g=>g.id!==id);goalId='';}),
 'add-holding':()=>holdingForm(),'edit-holding':()=>holdingForm(id),'delete-holding':()=>confirmAction('ลบการลงทุน','ลบรายการติดตามมูลค่านี้ ยอดบัญชีเงินจะไม่เปลี่ยน',()=>s.holdings=s.holdings.filter(h=>h.id!==id)),
 export:()=>download(JSON.stringify(s,null,2),'kanchit-bankbook-'+C.today()+'.json','application/json'),import:backupImport,csv:exportCsv,calendar:exportCalendar,
 reset:()=>confirmAction('ล้างข้อมูลทุกเครื่อง','จะลบบัญชี รายการเงิน เกม หนี้ และเป้าหมายทั้งหมด การลบจะซิงก์ไปทุกเครื่องเมื่อออนไลน์ ส่งออกสำรองก่อนหากต้องการเก็บข้อมูล กดย้อนกลับได้จนกว่าจะมีการแก้ไขถัดไป',()=>{s=M.fresh();sessionStorage.removeItem('kanchit-bridge-token');accountId=gameId=goalId='';}),
 undo:()=>{if(undoState){const old=undoState;undoState=null;s=old;persist();render();toast('ย้อนกลับแล้ว');}}
};await handlers[a]?.();}catch(err){toast(err.message);}});
document.addEventListener('change',e=>{const id=e.target.dataset.task;if(id){try{mutate(()=>{const g=s.games.find(g=>g.id===gameId),m=g.milestones.find(m=>m.id===id);m.done=e.target.checked;g.updatedAt=M.updated();});}catch(err){toast(err.message)}}});
document.addEventListener('input',e=>{if(e.target.id==='search'){filter=e.target.value;const pos=e.target.selectionStart;render();$('#search').focus();$('#search').setSelectionRange(pos,pos);}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'&&$('#dialog-form')){const nodes=[...$('#modal-root').querySelectorAll('button,input,select,textarea,a[href]')].filter(n=>!n.disabled);const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
window.addEventListener('storage',e=>{if(e.key!==M.KEY||!e.newValue||localStorage.getItem(M.KEY)!==e.newValue)return;if($('#dialog-form')){storageError='ข้อมูลเปลี่ยนจากอีกแท็บระหว่างแก้ไข กรุณาปิดแบบฟอร์มและรีเฟรชก่อนบันทึก';toast(storageError);return;}try{s=M.validate(JSON.parse(e.newValue));lastSavedRaw=e.newValue;undoState=null;storageError='';render();cloud?.enqueue();}catch{toast('อ่านข้อมูลจากอีกแท็บไม่ได้ กรุณารีเฟรช');}});
function renderSync(){
 const slot=$('#sync-slot');if(!slot)return;
 const mode=cloud?.mode||'connecting';
 const labels={connecting:'กำลังเชื่อมคลาวด์',synced:'เรียลไทม์ · ซิงก์แล้ว',pending:'บันทึกในเครื่องแล้ว · รอส่ง',saving:'กำลังบันทึกขึ้นคลาวด์',offline:'ออฟไลน์ · ข้อมูลรอส่งในเครื่อง',reconnecting:'กำลังต่อการเชื่อมต่อใหม่',migration:'พบข้อมูลเดิมในเครื่องนี้',conflict:'มีข้อมูลที่แก้พร้อมกัน',static:'รุ่น GitHub Pages · ข้อมูลเฉพาะเครื่อง',error:'ส่งข้อมูลไม่สำเร็จ','sign-in':'ลงชื่อเข้าใช้เพื่อซิงก์','account-changed':'บัญชีที่ลงชื่อเข้าใช้เปลี่ยนไป'};
 let detail=cloud?.message||((mode==='synced'&&cloud?.lastAt)?'อัปเดตล่าสุด '+when(cloud.lastAt):'มือถือและคอมต้องใช้บัญชี ChatGPT เดียวกัน');
 let actions='';
 if(mode==='migration'&&cloud?.migration){
  const count=v=>['accounts','transactions','games','bills','debts','goals','holdings'].reduce((n,k)=>n+(v?.[k]?.length||0),0);
  detail=`ข้อมูลเครื่องนี้ ${count(s)} รายการ · คลาวด์ ${count(cloud.migration.remote.document)} รายการ รวมตามรหัสรายการและตรวจข้อมูลที่แก้ชนกันก่อนส่ง`;
  actions=B('รวมข้อมูลเครื่องนี้กับคลาวด์','cloud-merge','primary')+B('ใช้ข้อมูลคลาวด์','cloud-use')+B('สำรองข้อมูลเครื่องนี้','export');
 }
 if(mode==='account-changed'){detail='ข้อมูลในเครื่องเป็นของบัญชีก่อนหน้า กรุณาสำรองก่อนสลับมาใช้ข้อมูลบัญชีปัจจุบัน ระบบจะไม่ส่งข้อมูลข้ามบัญชีเอง';actions=B('สำรองข้อมูลเครื่องนี้','export')+B('ใช้ข้อมูลบัญชีปัจจุบัน','cloud-use','primary');}
 if(mode==='conflict'&&cloud?.conflict){detail=`พบการแก้รายการเดียวกัน ${cloud.conflict.paths.length} จุด ระบบหยุดส่งไว้เพื่อให้คุณตรวจเลือก`;actions=B('ตรวจและเลือกรุ่นข้อมูล','cloud-conflict','primary')+B('สำรองข้อมูลเครื่องนี้','export');}
 if(mode==='offline'||mode==='error'||mode==='reconnecting')actions=B('ลองเชื่อมต่ออีกครั้ง','cloud-retry');
 if(mode==='sign-in')actions='<a class="btn primary" href="/signin-with-chatgpt?return_to=%2Fbankbook%2Findex.html" target="_top">ลงชื่อเข้าใช้ ChatGPT</a>';
 if(mode==='static'){detail='GitHub Pages ไม่มีฐานข้อมูลของแอป ใช้เว็บหลักเพื่อซิงก์ทุกเครื่อง และนำเข้าไฟล์สำรองเพื่อย้ายข้อมูลที่กรอกในหน้านี้';actions='<a class="btn primary" href="https://kanchit-money-notebook.kanfrankchot.chatgpt.site/" target="_blank" rel="noopener">เปิดเว็บเรียลไทม์ ↗</a>';}
 slot.innerHTML=`<section class="sync-bar" data-state="${mode}" role="status"><div><strong><span class="sync-dot"></span>${labels[mode]||'สถานะซิงก์'}</strong><p>${E(detail)}</p></div>${actions?'<div class="actions">'+actions+'</div>':''}</section>`;
}
function showCloudConflict(){
 const c=cloud?.conflict;if(!c)return;
 const names={accounts:'บัญชี',transactions:'รายการเงิน',games:'เกม',bills:'บิล',debts:'หนี้สิน',goals:'เป้าหมาย',holdings:'การลงทุน',profile:'แผนรายเดือน',loan:'แผนสินเชื่อ'};
 const groups=[...new Set(c.paths.map(p=>names[p.split('.')[1]?.split('[')[0]]||'ข้อมูลที่เกี่ยวข้อง'))].join(', ');
 modal('ตรวจข้อมูลที่แก้พร้อมกัน',`<div class="field full"><p>พบข้อมูลที่แก้ชนกันใน ${E(groups)} ข้อมูลส่วนที่แก้คนละจุดจะรวมให้อัตโนมัติ</p>${notice('ตัวเลือกนี้กำหนดว่าจะใช้ค่าจากเครื่องนี้หรือคลาวด์ในจุดที่ขัดแย้งกัน หากเป็นการลบบัญชีที่มีรายการใหม่เกี่ยวข้อง อาจต้องใช้ข้อมูลทั้งชุดจากฝั่งที่เลือก ควรสำรองทั้งสองฝั่งก่อน')}</div>`+sel('prefer','เมื่อข้อมูลขัดแย้งให้ใช้',[['local','ใช้ค่าจากเครื่องนี้'],['remote','ใช้ค่าจากคลาวด์']])+`<div class="field full actions">${B('สำรองข้อมูลเครื่องนี้','export')}${B('สำรองข้อมูลคลาวด์','cloud-export')}</div>`,v=>{cloud.resolveConflict(v.prefer);},'ใช้ค่าที่เลือกและซิงก์');
}
document.addEventListener('click',e=>{
 const button=e.target.closest('[data-action]');if(!button)return;
 try{const action=button.dataset.action;
 if(action==='cloud-merge')cloud.chooseMigration('merge');
 if(action==='cloud-use')confirmAction('ใช้ข้อมูลจากคลาวด์','ข้อมูลในเครื่องนี้จะถูกแทนที่ด้วยข้อมูลของบัญชีปัจจุบัน กรุณาสำรองข้อมูลที่ยังไม่ได้รวมก่อน',()=>cloud.chooseMigration('cloud'));
 if(action==='cloud-conflict')showCloudConflict();
 if(action==='cloud-export')download(JSON.stringify(cloud.conflict.remote,null,2),'kanchit-cloud-backup-'+C.today()+'.json','application/json');
 if(action==='cloud-retry'){if(cloud.ready){cloud.connect();void cloud.pull();void cloud.flush();}else void cloud.start();}
 }catch(err){toast(err.message);}
});
render();
cloud=new RealtimeSync({
 getLocal:()=>s,
 applyRemote:document=>{s=M.validate(document);const raw=JSON.stringify(s);localStorage.setItem(M.KEY,raw);lastSavedRaw=raw;undoState=null;render();},
 onStatus:()=>renderSync(),busy:()=>Boolean($('#dialog-form')),
});
void cloud.start();
window.addEventListener('online',()=>{if(cloud.ready){cloud.connect();void cloud.pull();void cloud.flush();}else void cloud.start();});
window.addEventListener('offline',()=>cloud.status('offline'));
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'){if(cloud.ready)void cloud.pull();else if(!cloud.migration)void cloud.start();}});


